<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('attendance.view_all');$pdo=staff_db();$date=$_GET['date']??date('Y-m-d');$s=$pdo->prepare("SELECT a.*,CONCAT(st.first_name,' ',COALESCE(st.last_name,'')) staff_name,st.staff_code FROM attendance a JOIN staff st ON st.id=a.staff_id WHERE a.attendance_date=? ORDER BY staff_name");$s->execute([$date]);$rows=$s->fetchAll();$pageTitle='Attendance Management';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Management</p><h1>Attendance management</h1></div><form method="get" class="inline-form"><input type="date" name="date" value="<?= h($date) ?>"><button class="btn">View</button></form></div><section class="staff-panel table-panel"><table><thead><tr><th>Staff</th><th>Clock in</th><th>Clock out</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['staff_name']) ?></td><td><?= $r['clock_in']?h(date('g:i A',strtotime($r['clock_in']))):'—' ?></td><td><?= $r['clock_out']?h(date('g:i A',strtotime($r['clock_out']))):'—' ?></td><td><?= h($r['status']) ?></td><td><?= h($r['notes']?:'—') ?></td></tr><?php endforeach;?></tbody></table></section></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
